// Splits CSV text into an array of records (arrays of cells), honoring
// double-quoted fields that may contain commas, newlines, or escaped quotes ("").
function parseRecords(text) {
  const records = [];
  let record = [];
  let cell = "";
  let inQuotes = false;
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"' && text[i + 1] === '"') {
        cell += '"';
        i++;
      } else if (c === '"') {
        inQuotes = false;
      } else {
        cell += c;
      }
    } else if (c === '"') {
      inQuotes = true;
    } else if (c === ",") {
      record.push(cell);
      cell = "";
    } else if (c === "\n" || c === "\r") {
      if (c === "\r" && text[i + 1] === "\n") i++;
      record.push(cell);
      records.push(record);
      record = [];
      cell = "";
    } else {
      cell += c;
    }
  }
  if (cell !== "" || record.length > 0) {
    record.push(cell);
    records.push(record);
  }
  return records;
}

function parseLine(line) {
  return parseRecords(line)[0] || [];
}

function parseCsv(text) {
  const [header, ...body] = parseRecords(text.trim());
  return body.map((cells) => {
    const row = {};
    header.forEach((h, i) => (row[h] = cells[i]));
    return row;
  });
}

